350	    /* 2026-08-08 嵌套导航：Settings 内点 WiFi/蓝牙行开子页时，
351	     * subpage_overlay 已存在（Settings 自己）。把当前 overlay 存为
352	     * subpage_parent，新子页盖在其上；close_subpage 恢复父 overlay。
353	     * 仅允许一层嵌套：subpage_parent 已非空（已在 WiFi/蓝牙子页里）
354	     * 时拒绝第三层，同时防点击抖动双重创建。 */
355	    LV_LOG_USER("show_subpage: %s (overlay=%p parent=%p)", title, subpage_overlay, subpage_parent);
356	    if (subpage_overlay) {
357	        if (subpage_parent) {
358	            /* 已在嵌套子页内（WiFi/蓝牙页再点行）：先关闭当前子页恢复父
359	             * overlay，再重新进入同一层嵌套——实现子页间切换与重复进入
360	             * 刷新（2026-08-09 修复：原逻辑直接 return，点 WiFi/蓝牙行
361	             * 毫无响应，日志只打一行） */
362	            lv_obj_t *p = subpage_parent;
363	            close_subpage();          /* 恢复父 overlay，parent 置空 */
364	            subpage_parent = p;       /* 保持嵌套层，继续开新子页 */
365	        } else {
366	            subpage_parent = subpage_overlay;   /* 保存父（Settings） */
367	        }
368	    }
369	
