376	    lv_obj_set_size(subpage_overlay, sw, sh);
377	    lv_obj_set_style_bg_color(subpage_overlay, lv_color_hex(COL_BG), 0);
378	    lv_obj_set_style_bg_opa(subpage_overlay, LV_OPA_COVER, 0);
