434	    if      (strcmp(title, "Music") == 0)    ui_music_create(content);
435	    else if (strcmp(title, "Games") == 0)    create_games_subpage(content);
436	    else if (strcmp(title, "Books") == 0)    ui_books_create(content);
437	    else if (strcmp(title, "Files") == 0)    ui_files_create(content);
438	    else if (strcmp(title, "AI") == 0)       create_ai_subpage(content);
439	    else if (strcmp(title, "Settings") == 0) ui_settings_create(content);
440	    else if (strcmp(title, "WiFi") == 0)     ui_wifi_create(content);
441	    else if (strcmp(title, "Bluetooth") == 0) ui_bt_create(content);
442	    else {
443	        lv_obj_t *placeholder = lv_label_create(content);
444	        lv_label_set_text(placeholder, "Coming soon...");
445	        lv_obj_set_style_text_font(placeholder, FONT_BODY, 0);
446	        lv_obj_set_style_text_color(placeholder, lv_color_hex(COL_SEC), 0);
447	    }
448	
449	    LV_LOG_USER("Open subpage: %s done (overlay y=%d)", title, lv_obj_get_y(subpage_overlay));
450	}
