309	/* 后台连接线程（wifi_connect 阻塞最长 60s，不能占 UI 线程） */
310	static void *dm_net_conn_worker(void *arg)
311	{
312	    const char *ssid = (const char *)arg;
313	    int my_gen = g_conn_gen;   /* 捕获本次连接代数 */
314	    int ret;
315	
316	    /* 密码可空（OPEN 网络）；wifi_connect 要求 WPA PSK 8~64 字节 */
317	    if (g_psk_buf[0])
318	        ret = wifi_connect((char *)ssid, RTW_SECURITY_WPA2_AES_PSK,
319	                           g_psk_buf, strlen(ssid), strlen(g_psk_buf),
320	                           0, NULL);
321	    else
322	        ret = wifi_connect((char *)ssid, RTW_SECURITY_OPEN,
323	                           NULL, strlen(ssid), 0, 0, NULL);
324	
325	    /* wifijianyi.md 脱逃判断：代数变了 = UI 已放弃本次连接（取消/退出），
326	     * 丢弃结果，不覆盖新状态（g_conn_state 保持由 UI 复位）。 */
327	    if (my_gen != g_conn_gen) {
328	        free((void *)ssid);
329	        return NULL;
330	    }
331	
332	    g_conn_state = (ret == RTW_SUCCESS) ? 2 : 3;
333	
334	    /* 连接成功 → 自动写入 wapi.conf（start_wifi.sh 开机自动重连）。
335	     * g_psk_buf 在 state==1 期间不会被 UI 修改（connect_start 拒绝并发）。 */
336	    if (ret == RTW_SUCCESS)
337	        dm_net_wifi_save_conf(ssid, g_psk_buf[0] ? g_psk_buf : "");
338	
339	    free((void *)ssid);
340	    return NULL;
341	}
