420	 * 防突发掉电导致配置文件损坏（半截 JSON = 开机连不上 WiFi）。 */
421	int dm_net_wifi_save_conf(const char *ssid, const char *psk)
422	{
423	    FILE *f;
424	    char dir[64];
425	    char tmp[64];
426	
427	    snprintf(dir, sizeof(dir), "/data/etc/wifi");
428	    mkdir(dir, 0755);   /* 目录可能不存在（首次写入） */
429	
430	    snprintf(tmp, sizeof(tmp), "/data/etc/wifi/wapi.conf.tmp");
431	    f = fopen(tmp, "w");
432	    if (f == NULL)
433	        return -1;
434	
435	    fprintf(f, "{\"ssid\":\"%s\",\"psk\":\"%s\",\"bssid\":\"\"}\n",
436	            ssid ? ssid : "", psk ? psk : "");
437	    if (fflush(f) != 0 || fsync(fileno(f)) != 0) {
438	        fclose(f);
439	        remove(tmp);
440	        return -1;
441	    }
442	    fclose(f);
443	
444	    if (rename(tmp, "/data/etc/wifi/wapi.conf") != 0) {
445	        remove(tmp);
446	        return -1;
447	    }
448	    return 0;
449	}
