/* 读取已保存配置的 SSID（wapi.conf JSON: {"ssid":"..","psk":".."}）
 * 2026-08-10：WiFi 子页"已保存网络"卡显示用；无文件/解析失败返回 -1 */
int dm_net_wifi_saved_ssid(char *buf, int buflen)
{
    FILE *f;
    char line[256];

    if (buf == NULL || buflen <= 0)
        return -1;
    buf[0] = '\0';

    f = fopen("/data/etc/wifi/wapi.conf", "r");
    if (f == NULL)
        return -1;

    if (fgets(line, sizeof(line), f) == NULL) {
        fclose(f);
        return -1;
    }
    fclose(f);

    /* 提取 "ssid":"..."（JSON 键值，pskip 防畸形输入） */
    char *p = strstr(line, "\"ssid\"");
    if (p == NULL)
        return -1;
    p = strchr(p, ':');
    if (p == NULL)
        return -1;
    p = strchr(p, '"');
    if (p == NULL)
        return -1;
    p++;                       /* 跳过开引号 */
    char *q = strchr(p, '"');
    if (q == NULL)
        return -1;
    size_t n = (size_t)(q - p);
    if (n >= (size_t)buflen)
        n = (size_t)buflen - 1;
    memcpy(buf, p, n);
    buf[n] = '\0';
    return 0;
}

