    lv_textarea_set_one_line(wifi_manual_psk_ta, true);
    lv_textarea_set_placeholder_text(wifi_manual_psk_ta, "密码（开放网络可留空）");
    lv_obj_set_style_text_font(wifi_manual_psk_ta, FONT_BODY, 0);

