/* 状态栏 wifi/bt 图标 ← 驱动实时状态（每秒由 clock timer 调用） */
void dm_net_status_refresh(void)
{
    if (status_wifi_lbl) {
        int up = dm_net_wifi_is_up();
        lv_obj_set_style_text_color(status_wifi_lbl,
            up ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    if (status_bt_lbl) {
        int on = dm_net_bt_is_on();   /* socket IPC 低频刷新在 dm_net.c 内部 */
        lv_obj_set_style_text_color(status_bt_lbl,
            on ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    /* 2026-08-10 子页/锁屏迷你状态栏图标同步刷新 */
    if (subpage_wifi_lbl) {
        int up = dm_net_wifi_is_up();
        lv_obj_set_style_text_color(subpage_wifi_lbl,
            up ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    if (subpage_bt_lbl) {
        int on = dm_net_bt_is_on();
        lv_obj_set_style_text_color(subpage_bt_lbl,
            on ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    if (standby_top_wifi_lbl) {
        int up = dm_net_wifi_is_up();
        lv_obj_set_style_text_color(standby_top_wifi_lbl,
            up ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
    if (standby_top_bt_lbl) {
        int on = dm_net_bt_is_on();
        lv_obj_set_style_text_color(standby_top_bt_lbl,
            on ? lv_color_hex(COL_BLUE) : lv_color_hex(COL_SEC), 0);
    }
}

